    <label for="transit">Transit Mode</label>
    <select id="transit">
      <option value="Foot Patrol (Walking)">Foot Patrol (Walking)</option>
      <option value="Two-Wheel Blitz (Bike/Scooter)">Two-Wheel Blitz (Bike/Scooter)</option>
      <option value="Urban Transit / Cruiser">Urban Transit / Cruiser</option>
    </select>
  </div>

  <div class="section">
    <label>Nearby Waypoints</label>
    <div class="stop-input-group">
      <input type="text" id="stopInput" placeholder="e.g., Local park, coffee shop, vinyl store...">
      <button class="btn-sec" onclick="addStop()">Add</button>
    </div>
    <div class="stop-list" id="stopList"></div>
  </div>

  <button class="btn-main" onclick="dealRoute()">Deal Route Card</button>

  <div class="route-card" id="routeCard">
