      <div class="route-title" id="cardTitle">Your Mission</div>
      <div class="meta-tag" id="cardMeta">Walking</div>
    </div>
    <ul class="checklist" id="checklist"></ul>

    <div class="actions-row">
      <button class="btn-sec" onclick="copyShareLink()">Copy Share Link</button>
      <button class="btn-sec" onclick="saveToUrl()">Save URL State</button>
    </div>
  </div>
</div>

<script>
  let stops = [];

  window.addEventListener('DOMContentLoaded', () => {
    const params = new URLSearchParams(window.location.search);
    if (params.has('t')) document.getElementById('timeBudget').value = params.get('t');
    if (params.has('m')) document.getElementById('mood').value = params.get('m');
    if (params.has('tr')) document.getElementById('transit').value = params.get('tr');
    if (params.has('s')) {
      stops = JSON.parse(decodeURIComponent(params.get('s')));
      updateStopList();
    }
    if (params.has('active') && params.get('active') === 'true') {
      dealRoute();
    }
  });

  function addStop() {
    const input = document.getElementById('stopInput');
    const val = input.value.trim();
    if (val) {
      stops.push(val);
      input.value = '';
      updateStopList();
    }
  }

  function removeStop(index) {
    stops.splice(index, 1);
    updateStopList();
  }

  function updateStopList() {
    const list = document.getElementById('stopList');
    list.innerHTML = '';
    stops.forEach((stop, i) => {
      const div = document.createElement('div');
      div.className = 'stop-item';
      div.innerHTML = `<span>${stop}</span><button onclick="removeStop(${i})">&times;</button>`;
      list.appendChild(div);
    });
  }

  function generateStateUrl(includeActive = false) {
    const t = document.getElementById('timeBudget').value;
    const m = document.getElementById('mood').value;
    const tr = document.getElementById('transit').value;
    const s = encodeURIComponent(JSON.stringify(stops));

    let url = `${window.location.origin}${window.location.pathname}?t=${encodeURIComponent(t)}&m=${encodeURIComponent(m)}&tr=${encodeURIComponent(tr)}&s=${s}`;
    if (includeActive) url += '&active=true';
    return url;
  }

  function saveToUrl() {
    const newUrl = generateStateUrl(false);
    window.history.pushState({}, '', newUrl);
  }

  function dealRoute() {
    const time = document.getElementById('timeBudget').value;
    const mood = document.getElementById('mood').value;
    const transit = document.getElementById('transit').value;

    if (stops.length === 0) {
      alert('Add at least one waypoint to mix your route.');
      return;
    }

    document.getElementById('cardMeta').innerText = transit.split(' (')[0];

    const titles = ["Operation: Ghost Protocol", "The Scenic Detour Matrix", "Gridline Shuffle", "The Horizon Blueprint"];
    document.getElementById('cardTitle').innerText = titles[Math.floor(Math.random() * titles.length)];

    const checklist = document.getElementById('checklist');
    checklist.innerHTML = '';

    const modifiers = {
      "Sunny & High Energy": ["Grab a cold drink first", "Take the longest, least shaded path intentionally", "Sprint the final block"],
      "Overcast, Moody & Melancholic": ["Put on a dark synth or heavy grunge soundtrack", "Find a spot to watch traffic pass", "Take a monochrome photo"],
      "Neon Night Vibes": ["Look for reflection pools on pavement", "Stick to illuminated alleys", "Keep pace with the streetlights"],
      "Rainy Day Slog": ["Embrace the wet soles; no stepping around puddles", "Seek immediate canvas awning shelter for 2 minutes", "Spot the lowest hanging cloud line"]
    };

    const selectedMods = modifiers[mood] || ["Keep eyes on the horizon"];

    // Add first modifier
    addChecklistItem(checklist, selectedMods[0]);

    // Shuffle and add unique waypoints
    const uniqueStops = [...new Set(stops)];
    uniqueStops.forEach((stop, index) => {
      let action = `Navigate to target: ${stop}`;
      if (index === 0) action = `Head straight to ${stop} via an alternate path`;
      if (index === uniqueStops.length - 1 && uniqueStops.length > 1) action = `Conclude operations at ${stop}`;
      addChecklistItem(checklist, action);
    });

    // Add second modifier based on time
    if (time.includes("Quick")) {
      addChecklistItem(checklist, "Maintain a rapid cadence; no lingering.");
    } else {
      addChecklistItem(checklist, selectedMods[1] || "Document one unusual architectural flaw along the route.");
    }

    document.getElementById('routeCard').style.display = 'block';
  }

  function addChecklistItem(parent, text) {
    const li = document.createElement('li');
    li.className = 'checklist-item';
    li.innerHTML = `<input type="checkbox"><span>${text}</span>`;
    parent.appendChild(li);
  }

  function copyShareLink() {
    const url = generateStateUrl(true);
    navigator.clipboard.writeText(url).then(() => {
      alert('Shareable route configuration copied to clipboard.');
    });
  }
</script>

</body>
</html>

